CREATE TABLE accounts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(255) NOT NULL CHECK (role IN ('PATIENT','RECEPTIONIST','ADMIN')), phone VARCHAR(255), gender VARCHAR(255), age INTEGER);
CREATE TABLE login_tokens (hash VARCHAR(255) PRIMARY KEY, account_id BIGINT NOT NULL REFERENCES accounts(id), expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE doctors (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL, specialty VARCHAR(255) NOT NULL, department VARCHAR(255) NOT NULL, room VARCHAR(255) NOT NULL, biography VARCHAR(4000));
CREATE TABLE schedules (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, doctor_id BIGINT NOT NULL REFERENCES doctors(id), date DATE NOT NULL, starts_at TIME NOT NULL, ends_at TIME NOT NULL, minutes INTEGER NOT NULL CHECK(minutes > 0), available BOOLEAN NOT NULL);
CREATE TABLE appointments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, schedule_id BIGINT NOT NULL REFERENCES schedules(id), account_id BIGINT REFERENCES accounts(id), serial INTEGER NOT NULL, slot_index INTEGER, age INTEGER NOT NULL, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL, gender VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL, claim_hash VARCHAR(255), created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(schedule_id, slot_index));
CREATE INDEX appointments_queue ON appointments(schedule_id, serial);
CREATE TABLE permissions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, account_id BIGINT NOT NULL REFERENCES accounts(id), doctor_id BIGINT NOT NULL REFERENCES doctors(id), edit_info BOOLEAN NOT NULL, edit_schedule BOOLEAN NOT NULL, edit_availability BOOLEAN NOT NULL, UNIQUE(account_id, doctor_id));
CREATE TABLE mail_jobs (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, recipient VARCHAR(255) NOT NULL, subject VARCHAR(255) NOT NULL, body VARCHAR(8000) NOT NULL, sent BOOLEAN NOT NULL, attempts INTEGER NOT NULL);
